import{_ as i,c as e,o,aj as a}from"./chunks/framework.CynFBi0q.js";const u=JSON.parse('{"title":"Python 实战训练营 - 知识结构目录","description":"","frontmatter":{},"headers":[],"relativePath":"handbook/python-practice/index.md","filePath":"handbook/python-practice/index.md","lastUpdated":1782569812000}'),r={name:"handbook/python-practice/index.md"};function t(n,l,d,s,c,h){return o(),e("div",null,[...l[0]||(l[0]=[a('<h1 id="python-实战训练营-知识结构目录" tabindex="-1">Python 实战训练营 - 知识结构目录 <a class="header-anchor" href="#python-实战训练营-知识结构目录" aria-label="Permalink to “Python 实战训练营 - 知识结构目录”">​</a></h1><h2 id="课程概览" tabindex="-1">课程概览 <a class="header-anchor" href="#课程概览" aria-label="Permalink to “课程概览”">​</a></h2><h3 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to “课程定位”">​</a></h3><p>针对 1-3 年初级 Python 开发工程师，系统提升工程化实战能力，达到一线大厂高级 Python 工程师水平</p><h3 id="核心特色" tabindex="-1">核心特色 <a class="header-anchor" href="#核心特色" aria-label="Permalink to “核心特色”">​</a></h3><ul><li><strong>大厂能力模型导向</strong>：直击开源框架及中间件底层核心原理</li><li><strong>实战驱动</strong>：手写 Web 框架、ORM 框架、异步任务引擎、微服务框架</li><li><strong>源码级教学</strong>：深入 Flask、Django、FastAPI、Celery、SQLAlchemy 等主流框架实现</li><li><strong>面试导向</strong>：每个模块配备面试要点和常见问题</li></ul><h3 id="课程结构" tabindex="-1">课程结构 <a class="header-anchor" href="#课程结构" aria-label="Permalink to “课程结构”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>内容</th></tr></thead><tbody><tr><td>周期</td><td>16周</td></tr><tr><td>模块</td><td>8大内容模块</td></tr><tr><td>实战</td><td>4大实战案例</td></tr><tr><td>加餐</td><td>4个热门面试主题</td></tr><tr><td>代码</td><td>完整代码仓库</td></tr></tbody></table><hr><h2 id="模块一-web-框架-3周" tabindex="-1">模块一：Web 框架（3周） <a class="header-anchor" href="#模块一-web-框架-3周" aria-label="Permalink to “模块一：Web 框架（3周）”">​</a></h2><h3 id="教学目标" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>掌握 Web 框架的基本原理与 WSGI/ASGI 规范</li><li>掌握路由系统设计：基于规则匹配与树形路由</li><li>掌握 Request/Response 对象模型与中间件链设计</li><li>掌握 Session 与 Cookie 机制的设计实现</li><li>掌握 Web 框架中 AOP（装饰器/中间件）方案</li><li>设计并实现模板引擎与静态资源服务</li></ol><h3 id="学习痛点" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>用过 Flask/Django，但不了解 WSGI/ASGI 底层原理，不知道请求从接收到响应的完整链路</li><li>面试时无法清晰阐述路由匹配原理，不知道如何设计 URL 分发系统</li><li>不清楚 Session 的存储抽象设计，无法支持 Redis/数据库等多后端切换</li><li>无法灵活运用中间件/装饰器解决鉴权、日志、限流、CORS 等横切关注点</li></ul><h3 id="第一周-web-框架核心设计与-wsgi-规范" tabindex="-1">第一周：Web 框架核心设计与 WSGI 规范 <a class="header-anchor" href="#第一周-web-框架核心设计与-wsgi-规范" aria-label="Permalink to “第一周：Web 框架核心设计与 WSGI 规范”">​</a></h3><h4 id="_1-1-web-框架概览与架构演进" tabindex="-1">1.1 Web 框架概览与架构演进 <a class="header-anchor" href="#_1-1-web-框架概览与架构演进" aria-label="Permalink to “1.1 Web 框架概览与架构演进”">​</a></h4><ul><li>从 CGI → WSGI → ASGI 的演进历程</li><li>WSGI 规范详解：<code>application(environ, start_response)</code></li><li>ASGI 异步规范：事件循环与异步协程</li><li>核心组件：Application、Router、Request、Response、Middleware</li><li><strong>开源实例分析</strong>：Flask 的微框架设计 vs Django 的全栈框架设计</li></ul><h4 id="_1-2-http-协议与-python-http-标准库" tabindex="-1">1.2 HTTP 协议与 Python HTTP 标准库 <a class="header-anchor" href="#_1-2-http-协议与-python-http-标准库" aria-label="Permalink to “1.2 HTTP 协议与 Python HTTP 标准库”">​</a></h4><ul><li>HTTP 请求/响应模型详解</li><li><code>http.server</code> 标准库源码分析</li><li><code>http.client</code> 客户端实现原理</li><li><strong>进阶语法</strong>：<code>socket</code> 编程与 HTTP Server 的关系</li><li><strong>代码演示</strong>：基于 <code>socket</code> 手写 HTTP Server，理解最底层通信</li></ul><h4 id="_1-3-路由系统设计与实现" tabindex="-1">1.3 路由系统设计与实现 <a class="header-anchor" href="#_1-3-路由系统设计与实现" aria-label="Permalink to “1.3 路由系统设计与实现”">​</a></h4><ul><li><strong>开源实例</strong>：Flask <code>@app.route</code> 装饰器原理、Django URLconf 设计、FastAPI APIRouter 对比</li><li><strong>核心原理</strong>： <ul><li>基于字典的静态路由匹配</li><li>基于正则的动态路由匹配（路径参数提取）</li><li>树形路由数据结构（类似 Radix Tree）</li></ul></li><li><strong>设计实现</strong>： <ul><li>Route 类设计：path、methods、handler、defaults</li><li>Rule 匹配引擎：<code>&lt;converter:variable&gt;</code> 语法</li><li>转换器系统：int、float、string、uuid、path</li></ul></li><li><strong>代码演示</strong>：实现支持动态参数的路由系统</li><li><strong>作业</strong>：实现自定义转换器（如手机号、日期格式）</li><li><strong>面试要点</strong>：路由匹配优先级、Flask <code>url_map</code> 底层数据结构</li></ul><h3 id="第二周-中间件与-aop-方案设计" tabindex="-1">第二周：中间件与 AOP 方案设计 <a class="header-anchor" href="#第二周-中间件与-aop-方案设计" aria-label="Permalink to “第二周：中间件与 AOP 方案设计”">​</a></h3><h4 id="_2-1-aop-设计模式详解" tabindex="-1">2.1 AOP 设计模式详解 <a class="header-anchor" href="#_2-1-aop-设计模式详解" aria-label="Permalink to “2.1 AOP 设计模式详解”">​</a></h4><ul><li><strong>装饰器模式</strong>（Decorator）：Python 装饰器原理与 <code>functools.wraps</code></li><li><strong>中间件模式</strong>（Middleware）：洋葱模型与请求/响应拦截</li><li><strong>上下文管理器</strong>（Context Manager）：<code>with</code> 语句与 <code>contextlib</code></li><li><strong>进阶语法</strong>：装饰器嵌套、带参数装饰器、类装饰器、<code>functools.wraps</code> 与 <code>__wrapped__</code></li></ul><h4 id="_2-2-开源框架中间件实现对比" tabindex="-1">2.2 开源框架中间件实现对比 <a class="header-anchor" href="#_2-2-开源框架中间件实现对比" aria-label="Permalink to “2.2 开源框架中间件实现对比”">​</a></h4><ul><li><strong>Django</strong>：MiddlewareMixin 链式调用机制（process_request → process_view → process_response → process_exception）</li><li><strong>Flask</strong>：before_request / after_request / teardown_request 钩子设计</li><li><strong>FastAPI</strong>：ASGI 中间件栈与 Dependency Injection 系统</li><li><strong>Starlette</strong>：纯 ASGI 中间件设计（BaseHTTPMiddleware）</li></ul><h4 id="_2-3-代码演示-为-web-框架提供-aop-支持" tabindex="-1">2.3 代码演示：为 Web 框架提供 AOP 支持 <a class="header-anchor" href="#_2-3-代码演示-为-web-框架提供-aop-支持" aria-label="Permalink to “2.3 代码演示：为 Web 框架提供 AOP 支持”">​</a></h4><ul><li>Access Log（访问日志）中间件</li><li>CORS（跨域资源共享）中间件</li><li>Auth（鉴权）中间件：JWT Token 校验</li><li>Rate Limiting（限流）中间件：基于令牌桶算法</li><li>Error Handling：统一异常处理与错误页面</li><li>Gzip 压缩中间件</li><li><strong>面试要点</strong>：中间件执行顺序、before/after 钩子与中间件区别、协程中间件与同步中间件混用问题</li></ul><h3 id="第三周-高级功能实现" tabindex="-1">第三周：高级功能实现 <a class="header-anchor" href="#第三周-高级功能实现" aria-label="Permalink to “第三周：高级功能实现”">​</a></h3><h4 id="_3-1-文件上传与下载" tabindex="-1">3.1 文件上传与下载 <a class="header-anchor" href="#_3-1-文件上传与下载" aria-label="Permalink to “3.1 文件上传与下载”">​</a></h4><ul><li><strong>开源实例</strong>：Flask <code>werkzeug.FileStorage</code>、Django <code>UploadFile</code>、FastAPI <code>UploadFile</code> 对比</li><li>文件上传：<code>multipart/form-data</code> 解析、流式上传、分片上传</li><li>文件下载：<code>Content-Disposition</code>、分块下载、断点续传</li><li><strong>进阶语法</strong>：<code>io.BytesIO</code>、<code>io.FileIO</code>、生成器与流式处理</li><li><strong>代码演示</strong>：实现大文件分片上传与断点续传</li></ul><h4 id="_3-2-模板引擎设计" tabindex="-1">3.2 模板引擎设计 <a class="header-anchor" href="#_3-2-模板引擎设计" aria-label="Permalink to “3.2 模板引擎设计”">​</a></h4><ul><li>模板引擎原理：词法分析 → 语法分析 → AST → 代码生成 → 渲染</li><li><strong>开源实例</strong>：Jinja2 架构分析（Lexer、Parser、Environment、Template）</li><li><strong>进阶语法</strong>：<code>string.Template</code>、<code>str.format_map</code>、f-string 的底层实现</li><li><strong>代码演示</strong>：在 Web 框架中集成 Jinja2 模板引擎</li><li><strong>设计模式</strong>：变量查找链、过滤器系统、模板继承与宏</li></ul><h4 id="_3-3-静态资源服务" tabindex="-1">3.3 静态资源服务 <a class="header-anchor" href="#_3-3-静态资源服务" aria-label="Permalink to “3.3 静态资源服务”">​</a></h4><ul><li><strong>开源实例</strong>：Django <code>staticfiles</code>、Flask <code>send_from_directory</code>、WhiteNoise 对比</li><li><strong>代码演示</strong>：设计可配置的静态资源处理器 <ul><li>FileResponse 流式传输</li><li>ETag / Last-Modified 缓存控制</li><li>Range 请求支持（大文件分块传输）</li></ul></li></ul><h4 id="_3-4-session-设计与实现" tabindex="-1">3.4 Session 设计与实现 <a class="header-anchor" href="#_3-4-session-设计与实现" aria-label="Permalink to “3.4 Session 设计与实现”">​</a></h4><ul><li><strong>开源实例</strong>：Flask-Session、Django Session Framework、itsdangerous 签名机制</li><li><strong>代码演示</strong>：Session API 设计与实现 <ul><li>基于内存的实现（dict + threading.Lock）</li><li>基于 Redis 的实现（支持 TTL 与序列化）</li><li>基于 JWT 的无状态方案</li></ul></li><li><strong>安全设计</strong>：Session 签名（HMAC）、防篡改、Secure / HttpOnly / SameSite Cookie 属性</li><li><strong>面试要点</strong>：Session vs JWT、CSRF 防护、分布式 Session 共享方案</li></ul><h3 id="模块一实战项目" tabindex="-1">模块一实战项目 <a class="header-anchor" href="#模块一实战项目" aria-label="Permalink to “模块一实战项目”">​</a></h3><p><strong>项目名称</strong>：手写 Web 框架实现用户注册登录系统</p><p><strong>项目内容</strong>：</p><ol><li>设计并实现一个完整的 WSGI Web 框架</li><li>设计并实现动态路由系统（支持路径参数、转换器、路由分组）</li><li>设计并实现中间件链（logging、CORS、auth、rate limit、error handling）</li><li>设计并实现静态资源服务器（ETag 缓存、Range 请求）</li><li>提供文件上传下载、模板渲染功能</li><li>压测、分析、优化性能（使用 <code>locust</code> + <code>pyinstrument</code>）</li><li>设计并实现 Session 机制（支持内存/Redis 双后端）</li><li>基于框架实现用户注册、登录、密码重置服务</li><li>利用中间件实现用户级限流与操作日志</li></ol><hr><h2 id="模块二-orm-框架-2周" tabindex="-1">模块二：ORM 框架（2周） <a class="header-anchor" href="#模块二-orm-框架-2周" aria-label="Permalink to “模块二：ORM 框架（2周）”">​</a></h2><h3 id="教学目标-1" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-1" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>掌握 ORM 框架的核心设计原理与元编程技术</li><li>掌握数据库连接池的设计与实现</li><li>掌握 SQL 构造器（Query Builder）与表达式系统设计</li><li>掌握模型映射（Model 与表映射）机制：元类、描述符、字段类型</li><li>掌握事务管理与嵌套事务实现（Savepoint）</li><li>掌握分库分表与读写分离框架设计思路</li></ol><h3 id="学习痛点-1" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-1" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>只会使用 SQLAlchemy/Django ORM，不了解 SQL 生成原理与元编程机制</li><li>遇到 N+1 查询问题不知道如何排查和优化</li><li>不了解连接池的工作原理和参数调优</li><li>复杂查询时 ORM 表达能力不足，只能退回裸 SQL</li></ul><h3 id="第四周-orm-核心设计与元编程" tabindex="-1">第四周：ORM 核心设计与元编程 <a class="header-anchor" href="#第四周-orm-核心设计与元编程" aria-label="Permalink to “第四周：ORM 核心设计与元编程”">​</a></h3><h4 id="_4-1-orm-框架概览与元编程基础" tabindex="-1">4.1 ORM 框架概览与元编程基础 <a class="header-anchor" href="#_4-1-orm-框架概览与元编程基础" aria-label="Permalink to “4.1 ORM 框架概览与元编程基础”">​</a></h4><ul><li>ORM 设计哲学：对象关系映射的本质与阻抗失配</li><li><strong>开源实例</strong>：SQLAlchemy、Django ORM、Tortoise ORM、Peewee 设计对比</li><li><strong>元编程核心技术</strong>： <ul><li><code>type()</code> 动态创建类与 <code>__init_subclass__</code></li><li>元类（Metaclass）：<code>__new__</code>、<code>__init__</code>、<code>__prepare__</code></li><li>描述符协议（Descriptor）：<code>__get__</code>、<code>__set__</code>、<code>__delete__</code></li><li><code>dataclasses</code> 与 <code>pydantic</code> 模型定义方式对比</li></ul></li><li>核心组件：Engine、Session、Model、Field、Query、Dialect</li></ul><h4 id="_4-2-数据库连接与连接池" tabindex="-1">4.2 数据库连接与连接池 <a class="header-anchor" href="#_4-2-数据库连接与连接池" aria-label="Permalink to “4.2 数据库连接与连接池”">​</a></h4><ul><li>DB-API 2.0 规范详解（PEP 249）</li><li><code>psycopg2</code> / <code>pymysql</code> 驱动原理</li><li>连接池设计原理与实现 <ul><li><strong>开源实例</strong>：SQLAlchemy Pool（QueuePool、NullPool、SingletonThreadPool）</li><li><strong>Python 实现</strong>：<code>queue.Queue</code> + <code>threading</code> 连接池</li><li>参数调优：pool_size、max_overflow、pool_recycle、pool_pre_ping</li></ul></li><li><strong>代码演示</strong>：实现线程安全的数据库连接池</li></ul><h4 id="_4-3-模型定义与字段系统" tabindex="-1">4.3 模型定义与字段系统 <a class="header-anchor" href="#_4-3-模型定义与字段系统" aria-label="Permalink to “4.3 模型定义与字段系统”">​</a></h4><ul><li><strong>元类实现模型注册</strong>： <ul><li><code>ModelBase.__new__</code> 收集字段元数据</li><li><code>_meta</code> 选项类设计（表名、字段列表、索引、唯一约束）</li><li>字段继承与抽象基类</li></ul></li><li><strong>字段类型系统</strong>： <ul><li>Field 基类设计：<code>db_type()</code>、<code>to_python()</code>、<code>get_db_prep_value()</code></li><li>字段类型实现：IntegerField、CharField、DateTimeField、TextField、JSONField</li><li>字段选项：null、default、unique、index、primary_key</li></ul></li><li><strong>描述符实现字段访问</strong>： <ul><li><code>Field.__get__</code>：从实例 <code>__dict__</code> 读取值</li><li><code>Field.__set__</code>：设置值并标记为 dirty</li></ul></li><li><strong>代码演示</strong>：使用元类实现完整的模型定义系统</li></ul><h3 id="第五周-query-builder-与事务管理" tabindex="-1">第五周：Query Builder 与事务管理 <a class="header-anchor" href="#第五周-query-builder-与事务管理" aria-label="Permalink to “第五周：Query Builder 与事务管理”">​</a></h3><h4 id="_5-1-query-builder-设计" tabindex="-1">5.1 Query Builder 设计 <a class="header-anchor" href="#_5-1-query-builder-设计" aria-label="Permalink to “5.1 Query Builder 设计”">​</a></h4><ul><li><strong>链式调用 API 设计</strong>： <ul><li><code>QuerySet</code> 惰性求值机制（Iterator Protocol + Generator）</li><li>链式方法：<code>filter()</code>、<code>exclude()</code>、<code>order_by()</code>、<code>limit()</code>、<code>offset()</code></li><li>查询表达式：<code>Q</code> 对象（AND/OR/NOT）、<code>F</code> 对象（字段间运算）</li></ul></li><li><strong>条件构造</strong>： <ul><li>查找表达式：<code>__eq</code>、<code>__gt</code>、<code>__in</code>、<code>__range</code>、<code>__contains</code>、<code>__icontains</code></li><li>SQL 编译器：表达式 → SQL 片段 + 参数列表</li><li>参数化查询与 SQL 注入防护</li></ul></li><li><strong>关联查询</strong>： <ul><li><code>select_related()</code>：JOIN 单表查询（一对一、外键）</li><li><code>prefetch_related()</code>：批量查询（多对多、反向关系）</li><li>N+1 查询问题原理与解决方案</li></ul></li><li><strong>聚合与分组</strong>：<code>annotate()</code> / <code>aggregate()</code> + <code>GROUP BY</code> 生成</li><li><strong>代码演示</strong>：实现支持惰性求值的类型安全 Query Builder</li></ul><h4 id="_5-2-crud-操作实现" tabindex="-1">5.2 CRUD 操作实现 <a class="header-anchor" href="#_5-2-crud-操作实现" aria-label="Permalink to “5.2 CRUD 操作实现”">​</a></h4><ul><li><strong>Insert</strong>：单条/批量插入、<code>ON CONFLICT</code> (Upsert)、<code>RETURNING</code> 语法</li><li><strong>Select</strong>：单条查询、列表查询、分页（offset/limit vs keyset pagination）、<code>only()</code> / <code>defer()</code> 延迟加载</li><li><strong>Update</strong>：更新指定字段、乐观锁（<code>version</code> 字段）、<code>F()</code> 表达式原子更新</li><li><strong>Delete</strong>：软删除（<code>is_deleted</code> 标记）、物理删除、级联删除策略</li><li><strong>代码演示</strong>：实现完整 CRUD 操作（含 SQL 日志输出）</li></ul><h4 id="_5-3-事务管理" tabindex="-1">5.3 事务管理 <a class="header-anchor" href="#_5-3-事务管理" aria-label="Permalink to “5.3 事务管理”">​</a></h4><ul><li>事务 ACID 特性与隔离级别（Read Uncommitted → Serializable）</li><li><strong>Python 事务管理方案</strong>： <ul><li>手动管理：<code>cursor.execute(&quot;BEGIN&quot;)</code> / <code>COMMIT</code> / <code>ROLLBACK</code></li><li>上下文管理器：<code>with transaction.atomic():</code></li><li>装饰器：<code>@transaction.atomic</code></li></ul></li><li>嵌套事务实现（Savepoint） <ul><li><code>SAVEPOINT sp_n</code> / <code>RELEASE SAVEPOINT sp_n</code> / <code>ROLLBACK TO SAVEPOINT sp_n</code></li></ul></li><li>事务传播行为与异常处理</li><li><strong>代码演示</strong>：实现基于上下文管理器的事务管理器（支持嵌套事务）</li></ul><h3 id="模块二实战项目" tabindex="-1">模块二实战项目 <a class="header-anchor" href="#模块二实战项目" aria-label="Permalink to “模块二实战项目”">​</a></h3><p><strong>项目名称</strong>：手写 ORM 框架实现博客系统数据层</p><p><strong>项目内容</strong>：</p><ol><li>设计并实现 ORM 核心（Engine、Session、Model 元类、Field 描述符）</li><li>实现模型定义系统（支持字段类型、选项、继承、Meta 配置）</li><li>实现完整 Query Builder（含 Q/F 表达式、关联查询、聚合、惰性求值）</li><li>实现事务管理（支持嵌套事务与 Savepoint）</li><li>实现连接池管理（支持参数调优与连接回收）</li><li>基于 ORM 实现博客系统数据访问层（User、Post、Comment、Tag 多对多关系）</li><li>性能优化：SQL 日志、慢查询分析、N+1 检测、<code>EXPLAIN</code> 分析</li></ol><hr><h2 id="模块三-异步编程与并发-2周" tabindex="-1">模块三：异步编程与并发（2周） <a class="header-anchor" href="#模块三-异步编程与并发-2周" aria-label="Permalink to “模块三：异步编程与并发（2周）”">​</a></h2><h3 id="教学目标-2" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-2" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>掌握 Python 异步编程核心原理：事件循环、协程、Future</li><li>掌握 <code>asyncio</code> 标准库与异步 IO 模型</li><li>掌握异步 Web 框架设计（ASGI 规范）</li><li>掌握多进程/多线程/协程的选型与混合使用</li><li>掌握异步数据库驱动与连接池设计</li><li>掌握并发任务调度与流程控制</li></ol><h3 id="学习痛点-2" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-2" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>对 <code>async/await</code> 停留在表面，不理解事件循环原理</li><li>多线程 vs 多进程 vs 协程选型困难，不知道何时用哪个</li><li>异步代码与同步代码混用时阻塞事件循环，性能反而下降</li><li>异步异常处理、超时控制、任务取消等复杂场景不知道怎么写</li></ul><h3 id="第六周-异步编程核心原理" tabindex="-1">第六周：异步编程核心原理 <a class="header-anchor" href="#第六周-异步编程核心原理" aria-label="Permalink to “第六周：异步编程核心原理”">​</a></h3><h4 id="_6-1-io-模型与事件循环" tabindex="-1">6.1 IO 模型与事件循环 <a class="header-anchor" href="#_6-1-io-模型与事件循环" aria-label="Permalink to “6.1 IO 模型与事件循环”">​</a></h4><ul><li><strong>IO 多路复用模型</strong>：select / poll / epoll 详解</li><li><strong>Python 事件循环实现</strong>： <ul><li><code>asyncio</code> 事件循环架构（Selector + Transport + Protocol）</li><li><code>selectors</code> 标准库：DefaultSelector、EpollSelector、KqueueSelector</li><li>libuv / uvloop 性能对比</li></ul></li><li><strong>协程原理</strong>： <ul><li>生成器协程（<code>yield</code> / <code>yield from</code>）→ 原生协程（<code>async</code> / <code>await</code>）的演进</li><li><code>@types.coroutine</code> vs <code>@asyncio.coroutine</code> vs <code>async def</code></li><li>协程状态机：CORO_CREATED → CORO_SUSPENDED → CORO_RUNNING → CORO_CLOSED</li></ul></li><li><strong>核心概念</strong>： <ul><li>Task vs Future vs Coroutine</li><li><code>asyncio.gather()</code> vs <code>asyncio.wait()</code> vs <code>asyncio.as_completed()</code></li><li><code>asyncio.Queue</code> 与生产者-消费者模式</li></ul></li><li><strong>代码演示</strong>：手写简化版事件循环（基于 <code>selectors</code> 模块）</li></ul><h4 id="_6-2-多进程与多线程" tabindex="-1">6.2 多进程与多线程 <a class="header-anchor" href="#_6-2-多进程与多线程" aria-label="Permalink to “6.2 多进程与多线程”">​</a></h4><ul><li><strong>多进程</strong>（<code>multiprocessing</code>）： <ul><li>Process / Pool / Queue / Pipe / Manager</li><li>进程间通信（IPC）与共享内存（<code>Value</code>、<code>Array</code>、<code>Manager</code>）</li><li>fork vs spawn vs forkserver 启动方式</li></ul></li><li><strong>多线程</strong>（<code>threading</code>）： <ul><li>Thread / Lock / RLock / Condition / Semaphore / Event</li><li>GIL（全局解释器锁）原理与影响：为什么 Python 多线程不能利用多核</li><li>GIL 对 IO 密集型 vs CPU 密集型任务的不同影响</li></ul></li><li><strong>concurrent.futures</strong>： <ul><li>ThreadPoolExecutor vs ProcessPoolExecutor</li><li><code>submit()</code> vs <code>map()</code>、<code>as_completed()</code> 结果收集</li><li>Future 对象与回调机制</li></ul></li><li><strong>代码演示</strong>：CPU 密集型用多进程、IO 密集型用多线程/协程的基准测试对比</li></ul><h3 id="第七周-异步框架与并发模式" tabindex="-1">第七周：异步框架与并发模式 <a class="header-anchor" href="#第七周-异步框架与并发模式" aria-label="Permalink to “第七周：异步框架与并发模式”">​</a></h3><h4 id="_7-1-asgi-规范与异步-web-框架" tabindex="-1">7.1 ASGI 规范与异步 Web 框架 <a class="header-anchor" href="#_7-1-asgi-规范与异步-web-框架" aria-label="Permalink to “7.1 ASGI 规范与异步 Web 框架”">​</a></h4><ul><li><strong>ASGI 规范详解</strong>： <ul><li>ASGI vs WSGI：异步事件模型 vs 同步调用模型</li><li>ASGI Application 签名：<code>async def app(scope, receive, send)</code></li><li>事件类型：<code>http.request</code>、<code>http.response.start</code>、<code>http.response.body</code></li></ul></li><li><strong>开源实例</strong>： <ul><li>Starlette：ASGI 框架基础层（Request/Response、路由、中间件）</li><li>FastAPI：Starlette + Pydantic + 依赖注入</li><li>Uvicorn / Hypercorn / Daphne：ASGI Server 对比</li></ul></li><li><strong>代码演示</strong>：将模块一的 WSGI 框架升级为 ASGI 异步框架</li></ul><h4 id="_7-2-异步数据库与缓存" tabindex="-1">7.2 异步数据库与缓存 <a class="header-anchor" href="#_7-2-异步数据库与缓存" aria-label="Permalink to “7.2 异步数据库与缓存”">​</a></h4><ul><li><strong>异步数据库驱动</strong>： <ul><li><code>asyncpg</code>（PostgreSQL）：基于 Protocol 的异步实现</li><li><code>aiomysql</code> / <code>asyncmy</code>（MySQL）：对比与选型</li><li>SQLAlchemy 2.0 <code>AsyncSession</code> 设计</li></ul></li><li><strong>异步连接池设计</strong>： <ul><li><code>asyncio.Queue</code> 实现异步连接池</li><li>连接超时、空闲回收、健康检查</li></ul></li><li><strong>异步 Redis</strong>： <ul><li><code>redis-py</code> async 模式、<code>aioredis</code> 演进</li><li>Pipeline、发布订阅的异步实现</li></ul></li><li><strong>代码演示</strong>：实现异步 ORM（基于元类 + <code>async/await</code>）</li></ul><h4 id="_7-3-并发模式与流程控制" tabindex="-1">7.3 并发模式与流程控制 <a class="header-anchor" href="#_7-3-并发模式与流程控制" aria-label="Permalink to “7.3 并发模式与流程控制”">​</a></h4><ul><li><strong>生产者-消费者模式</strong>：<code>asyncio.Queue</code> 与背压控制</li><li><strong>限并发模式</strong>：<code>asyncio.Semaphore</code> 与有界队列</li><li><strong>扇出/扇入</strong>（Fan-out/Fan-in）：<code>gather</code> + <code>TaskGroup</code>（Python 3.11+）</li><li><strong>超时与取消</strong>：<code>asyncio.wait_for()</code>、<code>asyncio.timeout()</code>、<code>Task.cancel()</code> 与 <code>CancelledError</code></li><li><strong>异常处理</strong>：<code>gather(return_exceptions=True)</code>、<code>asyncio.gather</code> 异常传播</li><li><strong>异步上下文管理器</strong>：<code>async with</code> 与 <code>asynccontextmanager</code></li><li><strong>异步迭代器</strong>：<code>async for</code> 与 <code>__aiter__</code> / <code>__anext__</code></li><li><strong>代码演示</strong>：实现异步爬虫调度器（限并发、超时、重试、结果聚合）</li></ul><h3 id="模块三实战项目" tabindex="-1">模块三实战项目 <a class="header-anchor" href="#模块三实战项目" aria-label="Permalink to “模块三实战项目”">​</a></h3><p><strong>项目名称</strong>：异步高并发 Web 框架实现实时协作系统</p><p><strong>项目内容</strong>：</p><ol><li>基于 ASGI 规范实现异步 Web 框架（支持 <code>async def</code> 路由处理器）</li><li>实现异步中间件链（异步 CORS、异步 Auth、异步 Rate Limit）</li><li>实现异步 ORM（基于 <code>asyncpg</code> + 元类，支持异步 CRUD 与连接池）</li><li>实现 WebSocket 支持（实时双向通信）</li><li>实现异步任务调度器（限并发、超时控制、重试机制）</li><li>基于框架实现实时协作系统（在线文档协作 / 实时聊天）</li><li>压测对比同步 vs 异步框架的性能差异（QPS、延迟、资源占用）</li></ol><hr><h2 id="模块四-微服务框架-3周" tabindex="-1">模块四：微服务框架（3周） <a class="header-anchor" href="#模块四-微服务框架-3周" aria-label="Permalink to “模块四：微服务框架（3周）”">​</a></h2><h3 id="教学目标-3" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-3" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>掌握微服务架构核心概念与设计原则</li><li>掌握 RPC 框架的设计与实现（gRPC + Protocol Buffers）</li><li>掌握服务注册与发现机制（Consul / Etcd）</li><li>掌握负载均衡与熔断降级设计</li><li>掌握分布式链路追踪（OpenTelemetry）</li><li>掌握微服务网关设计（API Gateway）</li></ol><h3 id="学习痛点-3" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-3" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>微服务拆分粒度难以把握，拆太细运维成本高，拆太粗失去意义</li><li>服务间通信性能瓶颈，同步调用导致雪崩</li><li>服务治理复杂度高（注册发现、限流熔断、配置中心）</li><li>分布式调试困难，一个请求跨多个服务，出问题难以定位</li></ul><h3 id="第八周-rpc-框架设计与-grpc" tabindex="-1">第八周：RPC 框架设计与 gRPC <a class="header-anchor" href="#第八周-rpc-框架设计与-grpc" aria-label="Permalink to “第八周：RPC 框架设计与 gRPC”">​</a></h3><h4 id="_8-1-微服务架构概览" tabindex="-1">8.1 微服务架构概览 <a class="header-anchor" href="#_8-1-微服务架构概览" aria-label="Permalink to “8.1 微服务架构概览”">​</a></h4><ul><li>单体 vs SOA vs 微服务架构演进</li><li>微服务设计原则：单一职责、自治、去中心化、故障隔离</li><li><strong>开源实例</strong>：Nameko、FastAPI + gRPC、FastStream、Faust 对比</li><li>Python 微服务生态 vs Go/Java 微服务生态的差异与选型</li></ul><h4 id="_8-2-rpc-核心原理" tabindex="-1">8.2 RPC 核心原理 <a class="header-anchor" href="#_8-2-rpc-核心原理" aria-label="Permalink to “8.2 RPC 核心原理”">​</a></h4><ul><li>RPC 通信模型：同步调用、异步调用、流式调用</li><li>序列化协议：JSON、MessagePack、Protobuf、Thrift 对比</li><li>网络传输：TCP 长连接、HTTP/2 多路复用</li><li><strong>代码演示</strong>：基于 <code>socket</code> + <code>pickle</code> 实现简单 RPC 框架</li></ul><h4 id="_8-3-grpc-深度解析" tabindex="-1">8.3 gRPC 深度解析 <a class="header-anchor" href="#_8-3-grpc-深度解析" aria-label="Permalink to “8.3 gRPC 深度解析”">​</a></h4><ul><li>Protocol Buffers 语法与 <code>protoc</code> 代码生成</li><li>gRPC 四种通信模式： <ul><li>Unary RPC（一元调用）</li><li>Server Streaming RPC（服务端流）</li><li>Client Streaming RPC（客户端流）</li><li>Bidirectional Streaming RPC（双向流）</li></ul></li><li>拦截器（Interceptor）机制：<code>grpc.ServerInterceptor</code> / <code>grpc.ClientInterceptor</code></li><li>流控与背压（Flow Control / Backpressure）</li><li><strong>代码演示</strong>：gRPC 服务端与客户端实现（含拦截器、超时、重试）</li></ul><h3 id="第九周-服务治理" tabindex="-1">第九周：服务治理 <a class="header-anchor" href="#第九周-服务治理" aria-label="Permalink to “第九周：服务治理”">​</a></h3><h4 id="_9-1-服务注册与发现" tabindex="-1">9.1 服务注册与发现 <a class="header-anchor" href="#_9-1-服务注册与发现" aria-label="Permalink to “9.1 服务注册与发现”">​</a></h4><ul><li>注册中心选型：Consul、Etcd、Nacos、ZooKeeper 对比</li><li><strong>Python 实现</strong>： <ul><li>服务注册：启动时向注册中心写入服务信息（IP、端口、元数据）</li><li>心跳保活：定时续约与 TTL 机制</li><li>服务发现：客户端缓存 + 监听变更（Watch / Long Polling）</li></ul></li><li><strong>代码演示</strong>：基于 <code>python-consul</code> / <code>aioetcd</code> 实现服务注册发现客户端</li></ul><h4 id="_9-2-负载均衡" tabindex="-1">9.2 负载均衡 <a class="header-anchor" href="#_9-2-负载均衡" aria-label="Permalink to “9.2 负载均衡”">​</a></h4><ul><li>客户端负载均衡 vs 服务端负载均衡</li><li>负载均衡算法： <ul><li>轮询（Round Robin）、加权轮询（Weighted Round Robin）</li><li>随机（Random）、加权随机</li><li>最少连接（Least Connections）</li><li>一致性哈希（Consistent Hashing）：虚拟节点与环设计</li></ul></li><li>健康检查机制：主动探测 vs 被动反馈</li><li><strong>代码演示</strong>：实现客户端负载均衡器（支持多算法切换）</li></ul><h4 id="_9-3-熔断、降级与限流" tabindex="-1">9.3 熔断、降级与限流 <a class="header-anchor" href="#_9-3-熔断、降级与限流" aria-label="Permalink to “9.3 熔断、降级与限流”">​</a></h4><ul><li><strong>熔断器模式</strong>（Circuit Breaker）： <ul><li>状态机：Closed → Open → Half-Open</li><li>滑动窗口统计：计数器 vs 时间窗口</li><li><strong>开源实例</strong>：<code>pybreaker</code>、<code>circuitbreaker</code> 库原理</li></ul></li><li><strong>降级策略</strong>： <ul><li>返回默认值、返回缓存数据、返回降级响应</li><li>降级链路设计（主 → 备 → 兜底）</li></ul></li><li><strong>限流算法</strong>： <ul><li>计数器法、滑动窗口法</li><li>令牌桶（Token Bucket）：<code>asyncio</code> 实现异步令牌桶</li><li>漏桶（Leaky Bucket）：平滑流量</li></ul></li><li><strong>代码演示</strong>：实现熔断 + 降级 + 限流一体化的服务防护组件</li></ul><h3 id="第十周-可观测性与-api-网关" tabindex="-1">第十周：可观测性与 API 网关 <a class="header-anchor" href="#第十周-可观测性与-api-网关" aria-label="Permalink to “第十周：可观测性与 API 网关”">​</a></h3><h4 id="_10-1-分布式链路追踪" tabindex="-1">10.1 分布式链路追踪 <a class="header-anchor" href="#_10-1-分布式链路追踪" aria-label="Permalink to “10.1 分布式链路追踪”">​</a></h4><ul><li>链路追踪核心概念：Trace、Span、Baggage、Context Propagation</li><li>OpenTelemetry Python SDK <ul><li>Tracer API、Span 创建与属性、Context 注入与提取</li><li>自动 instrumentation（Flask / FastAPI / SQLAlchemy / Redis）</li></ul></li><li>采样策略：头部采样、尾部采样、概率采样</li><li><strong>代码演示</strong>：为微服务框架集成 OpenTelemetry 链路追踪</li></ul><h4 id="_10-2-指标监控" tabindex="-1">10.2 指标监控 <a class="header-anchor" href="#_10-2-指标监控" aria-label="Permalink to “10.2 指标监控”">​</a></h4><ul><li>Metrics 类型：Counter、Gauge、Histogram、Summary</li><li><code>prometheus_client</code> Python 库 <ul><li>自定义指标定义与注册</li><li>Histogram 分桶策略</li><li><code>/metrics</code> endpoint 暴露</li></ul></li><li><strong>代码演示</strong>：实现应用指标采集器（QPS、延迟分布、错误率、资源占用）</li></ul><h4 id="_10-3-结构化日志" tabindex="-1">10.3 结构化日志 <a class="header-anchor" href="#_10-3-结构化日志" aria-label="Permalink to “10.3 结构化日志”">​</a></h4><ul><li><strong>开源库</strong>：<code>structlog</code>、<code>loguru</code>、<code>python-json-logger</code> 对比与原理</li><li>结构化日志设计（JSON 格式 + 上下文绑定）</li><li>日志与链路追踪关联（Trace ID / Span ID 注入日志）</li><li><strong>代码演示</strong>：实现结构化日志库（支持上下文绑定与 Trace 关联）</li></ul><h4 id="_10-4-api-网关设计" tabindex="-1">10.4 API 网关设计 <a class="header-anchor" href="#_10-4-api-网关设计" aria-label="Permalink to “10.4 API 网关设计”">​</a></h4><ul><li>网关核心功能：路由转发、协议转换、认证鉴权、限流熔断、日志监控</li><li><strong>开源实例</strong>：Kong、APISIX、Traefik 网关原理</li><li><strong>代码演示</strong>：基于 ASGI 实现轻量级 API 网关（路由、鉴权、限流、日志）</li></ul><h3 id="模块四实战项目" tabindex="-1">模块四实战项目 <a class="header-anchor" href="#模块四实战项目" aria-label="Permalink to “模块四实战项目”">​</a></h3><p><strong>项目名称</strong>：微服务框架实现电商订单系统</p><p><strong>项目内容</strong>：</p><ol><li>设计并实现 gRPC 服务间通信框架（含拦截器、超时、重试）</li><li>实现服务注册与发现（基于 Consul / Etcd）</li><li>实现客户端负载均衡（支持多算法）</li><li>实现熔断 + 降级 + 限流防护组件</li><li>实现分布式链路追踪（OpenTelemetry）+ 指标监控（Prometheus）</li><li>实现结构化日志（Trace ID 关联）</li><li>基于微服务框架实现电商系统（用户服务、商品服务、订单服务、支付服务）</li></ol><hr><h2 id="模块五-分布式系统与中间件-2周" tabindex="-1">模块五：分布式系统与中间件（2周） <a class="header-anchor" href="#模块五-分布式系统与中间件-2周" aria-label="Permalink to “模块五：分布式系统与中间件（2周）”">​</a></h2><h3 id="教学目标-4" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-4" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>掌握分布式系统核心概念：CAP、BASE、一致性模型</li><li>掌握分布式锁设计与实现（Redis / Etcd / ZooKeeper）</li><li>掌握分布式任务调度框架设计（Celery 架构原理）</li><li>掌握分布式 ID 生成方案（Snowflake / UUID / Leaf）</li><li>掌握消息队列（Kafka / RabbitMQ / Redis Stream）在 Python 中的使用</li><li>掌握缓存系统设计（本地缓存 + Redis + 多级缓存）</li></ol><h3 id="学习痛点-4" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-4" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>分布式锁实现总出问题：锁过期、锁释放、网络分区</li><li>Celery 用了很久但不理解 Broker / Worker / Beat 的工作原理</li><li>消息队列选型困难，Kafka vs RabbitMQ vs Redis Stream 不知道怎么选</li><li>缓存穿透/击穿/雪崩问题频发，不知道如何系统化防护</li></ul><h3 id="第十一周-分布式基础与缓存系统" tabindex="-1">第十一周：分布式基础与缓存系统 <a class="header-anchor" href="#第十一周-分布式基础与缓存系统" aria-label="Permalink to “第十一周：分布式基础与缓存系统”">​</a></h3><h4 id="_11-1-分布式系统基础" tabindex="-1">11.1 分布式系统基础 <a class="header-anchor" href="#_11-1-分布式系统基础" aria-label="Permalink to “11.1 分布式系统基础”">​</a></h4><ul><li>CAP 定理与权衡：一致性 vs 可用性 vs 分区容错</li><li>BASE 理论：基本可用、软状态、最终一致性</li><li>一致性模型：强一致性、最终一致性、因果一致性、读己之写</li><li>分布式问题：脑裂、网络分区、时钟漂移</li></ul><h4 id="_11-2-分布式锁实现" tabindex="-1">11.2 分布式锁实现 <a class="header-anchor" href="#_11-2-分布式锁实现" aria-label="Permalink to “11.2 分布式锁实现”">​</a></h4><ul><li><strong>基于 Redis</strong>： <ul><li><code>SET key value NX PX</code> 原子操作</li><li>锁续约（Watchdog 机制）：后台线程定时续期</li><li>Lua 脚本保证释放锁的原子性</li><li>RedLock 算法：多节点投票与争议分析</li></ul></li><li><strong>基于 Etcd</strong>： <ul><li>Lease + TTL 机制</li><li>事务（Txn）保证原子性</li><li>Watch 监听锁释放</li></ul></li><li><strong>基于 ZooKeeper</strong>： <ul><li>临时有序节点 + Watch 机制</li><li>羊群效应与优化方案</li></ul></li><li><strong>代码演示</strong>：实现通用分布式锁抽象层（支持 Redis / Etcd 双后端）</li></ul><h4 id="_11-3-缓存系统设计" tabindex="-1">11.3 缓存系统设计 <a class="header-anchor" href="#_11-3-缓存系统设计" aria-label="Permalink to “11.3 缓存系统设计”">​</a></h4><ul><li><strong>本地缓存实现</strong>： <ul><li><code>functools.lru_cache</code> 源码分析</li><li><code>cachetools</code> 库：LRU、LFU、TTL Cache 实现</li><li>线程安全缓存：<code>threading.Lock</code> vs <code>multiprocessing.Manager</code></li></ul></li><li><strong>Redis 缓存</strong>： <ul><li><code>redis-py</code> 连接池、Pipeline、事务</li><li>Lua 脚本执行与原子操作</li><li>发布订阅（Pub/Sub）模式</li></ul></li><li><strong>多级缓存架构</strong>： <ul><li>L1 本地缓存（进程内）+ L2 Redis 缓存（分布式）</li><li>缓存一致性：延时双删、消息队列通知</li></ul></li><li><strong>缓存防护</strong>： <ul><li>缓存穿透：布隆过滤器（<code>pybloom-live</code>）、空值缓存</li><li>缓存击穿：互斥锁（<code>threading.Lock</code> / Redis <code>SETNX</code>）、逻辑过期</li><li>缓存雪崩：随机过期时间、多级兜底</li></ul></li><li><strong>代码演示</strong>：实现多级缓存系统（含防护组件）</li></ul><h3 id="第十二周-分布式任务调度与消息队列" tabindex="-1">第十二周：分布式任务调度与消息队列 <a class="header-anchor" href="#第十二周-分布式任务调度与消息队列" aria-label="Permalink to “第十二周：分布式任务调度与消息队列”">​</a></h3><h4 id="_12-1-celery-架构深度解析" tabindex="-1">12.1 Celery 架构深度解析 <a class="header-anchor" href="#_12-1-celery-架构深度解析" aria-label="Permalink to “12.1 Celery 架构深度解析”">​</a></h4><ul><li><strong>Celery 核心架构</strong>： <ul><li>Broker（消息代理）：RabbitMQ / Redis / Amazon SQS</li><li>Worker（工作进程）：prefork / eventlet / gevent 并发模型</li><li>Beat（定时调度）：crontab 表达式与持久化调度</li><li>Backend（结果存储）：RPC / Redis / Database</li></ul></li><li><strong>任务设计</strong>： <ul><li><code>@app.task</code> 装饰器原理与任务注册</li><li>任务参数序列化：JSON / Pickle / MessagePack</li><li>任务重试机制：<code>autoretry_for</code>、<code>max_retries</code>、指数退避</li><li>任务链：<code>chain</code> / <code>group</code> / <code>chord</code> / <code>chunks</code></li></ul></li><li><strong>任务监控</strong>： <ul><li>Flower 监控面板</li><li>任务状态追踪与超时处理</li><li>死信队列与失败任务重放</li></ul></li><li><strong>代码演示</strong>：实现基于 Celery 的异步任务处理系统</li></ul><h4 id="_12-2-消息队列" tabindex="-1">12.2 消息队列 <a class="header-anchor" href="#_12-2-消息队列" aria-label="Permalink to “12.2 消息队列”">​</a></h4><ul><li><strong>Kafka 在 Python 中的使用</strong>： <ul><li><code>confluent-kafka-python</code> vs <code>kafka-python</code> 对比</li><li>Producer：分区策略、acks 语义、批次发送</li><li>Consumer：消费者组、分区分配、offset 管理</li><li><strong>代码演示</strong>：Kafka 日志收集系统</li></ul></li><li><strong>RabbitMQ 在 Python 中的使用</strong>： <ul><li><code>pika</code> 库：Connection / Channel / Exchange / Queue</li><li>Exchange 类型：direct、fanout、topic、headers</li><li>消息确认机制：auto-ack / manual-ack / nack</li><li>死信交换器（DLX）与延时队列</li><li><strong>代码演示</strong>：RabbitMQ 订单异步处理系统</li></ul></li><li><strong>Redis Stream</strong>： <ul><li>Stream 数据结构与消费组</li><li>与 Kafka/RabbitMQ 的差异与适用场景</li><li><strong>代码演示</strong>：Redis Stream 实时消息系统</li></ul></li></ul><h4 id="_12-3-分布式-id-生成" tabindex="-1">12.3 分布式 ID 生成 <a class="header-anchor" href="#_12-3-分布式-id-生成" aria-label="Permalink to “12.3 分布式 ID 生成”">​</a></h4><ul><li><strong>UUID</strong>：v1（时间+MAC）/ v4（随机）/ v7（时间+随机）对比</li><li><strong>Snowflake</strong>： <ul><li>64 位结构：时间戳 + 工作机器 ID + 序列号</li><li>时钟回拨问题与解决方案</li><li><strong>代码演示</strong>：实现 Snowflake ID 生成器</li></ul></li><li><strong>数据库自增 ID</strong>： <ul><li>步长方案（分库分表场景）</li><li>号段模式（Leaf-Segment）</li></ul></li><li><strong>代码演示</strong>：实现通用 ID 生成抽象层</li></ul><h3 id="模块五实战项目" tabindex="-1">模块五实战项目 <a class="header-anchor" href="#模块五实战项目" aria-label="Permalink to “模块五实战项目”">​</a></h3><p><strong>项目名称</strong>：分布式系统实现秒杀与异步订单</p><p><strong>项目内容</strong>：</p><ol><li>实现分布式锁（Redis + Etcd 双后端，含锁续约）</li><li>实现多级缓存系统（本地 + Redis，含穿透/击穿/雪崩防护）</li><li>基于 Celery 实现异步订单处理（含任务重试、死信队列）</li><li>基于 RabbitMQ 实现订单异步创建与库存扣减</li><li>基于 Kafka 实现操作日志收集</li><li>实现 Snowflake 分布式 ID 生成器</li><li>完整实现秒杀系统（限流 → 缓存 → 分布式锁 → 异步下单 → 消息通知）</li></ol><hr><h2 id="模块六-数据管道与-etl-2周" tabindex="-1">模块六：数据管道与 ETL（2周） <a class="header-anchor" href="#模块六-数据管道与-etl-2周" aria-label="Permalink to “模块六：数据管道与 ETL（2周）”">​</a></h2><h3 id="教学目标-5" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-5" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>掌握数据管道架构设计原理</li><li>掌握 Python 数据处理核心库：pandas、polars、numpy</li><li>掌握 ETL 流程设计：抽取、转换、加载</li><li>掌握 Airflow 工作流调度框架</li><li>掌握数据质量监控与数据血缘追踪</li><li>掌握大数据处理框架：Spark（PySpark）基础</li></ol><h3 id="学习痛点-5" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-5" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>数据处理脚本越写越乱，没有工程化思维</li><li>pandas 处理大数据集时内存溢出，不知道如何优化</li><li>ETL 流程没有调度系统，全靠 crontab 硬编码</li><li>数据质量问题发现太晚，上线后才发现数据错误</li></ul><h3 id="第十三周-数据处理与-etl-工程" tabindex="-1">第十三周：数据处理与 ETL 工程 <a class="header-anchor" href="#第十三周-数据处理与-etl-工程" aria-label="Permalink to “第十三周：数据处理与 ETL 工程”">​</a></h3><h4 id="_13-1-数据处理核心库" tabindex="-1">13.1 数据处理核心库 <a class="header-anchor" href="#_13-1-数据处理核心库" aria-label="Permalink to “13.1 数据处理核心库”">​</a></h4><ul><li><strong>pandas 进阶</strong>： <ul><li>DataFrame 内部数据结构：BlockManager 与内存布局</li><li>索引与对齐机制：Index、MultiIndex、reindex</li><li>性能优化：向量化操作、<code>eval()</code>、分类类型（Categorical）</li><li>大数据处理：分块读取（<code>chunksize</code>）、<code>dask</code> 延迟计算</li></ul></li><li><strong>polars 对比</strong>： <ul><li>Rust 内核 + Python 接口，惰性执行引擎</li><li>多线程并行处理 vs pandas 单线程</li><li>流式处理（Streaming）解决内存问题</li><li><strong>代码演示</strong>：pandas vs polars 性能基准测试</li></ul></li><li><strong>numpy 底层</strong>： <ul><li>ndarray 内存布局：C-order vs Fortran-order</li><li>广播机制（Broadcasting）原理</li><li>向量化运算与 ufunc</li></ul></li></ul><h4 id="_13-2-etl-流程设计" tabindex="-1">13.2 ETL 流程设计 <a class="header-anchor" href="#_13-2-etl-流程设计" aria-label="Permalink to “13.2 ETL 流程设计”">​</a></h4><ul><li><strong>抽取（Extract）</strong>： <ul><li>多数据源接入：MySQL、PostgreSQL、MongoDB、API、CSV/Parquet</li><li>增量抽取：基于时间戳、基于 CDC（Change Data Capture）</li><li>连接池与批量读取优化</li></ul></li><li><strong>转换（Transform）</strong>： <ul><li>数据清洗：缺失值处理、异常值检测、去重</li><li>数据转换：类型转换、标准化、编码（One-Hot / Label）</li><li>数据聚合：groupby + agg、窗口函数、滚动统计</li><li>数据关联：merge / join 策略与内存优化</li></ul></li><li><strong>加载（Load）</strong>： <ul><li>批量写入：<code>executemany</code>、COPY 命令、<code>LOAD DATA INFILE</code></li><li>写入优化：事务批量提交、索引延迟创建</li><li>幂等加载：UPSERT / MERGE 语义</li></ul></li><li><strong>代码演示</strong>：实现通用 ETL 框架（支持多源接入、数据清洗、批量加载）</li></ul><h3 id="第十四周-工作流调度与数据质量" tabindex="-1">第十四周：工作流调度与数据质量 <a class="header-anchor" href="#第十四周-工作流调度与数据质量" aria-label="Permalink to “第十四周：工作流调度与数据质量”">​</a></h3><h4 id="_14-1-airflow-工作流调度" tabindex="-1">14.1 Airflow 工作流调度 <a class="header-anchor" href="#_14-1-airflow-工作流调度" aria-label="Permalink to “14.1 Airflow 工作流调度”">​</a></h4><ul><li><strong>Airflow 核心架构</strong>： <ul><li>Scheduler（调度器）、Executor（执行器）、Worker</li><li>DAG（有向无环图）定义与 Task 依赖</li><li>Executor 选型：LocalExecutor / CeleryExecutor / KubernetesExecutor</li></ul></li><li><strong>DAG 开发</strong>： <ul><li><code>@dag</code> / <code>@task</code> 装饰器 API（TaskFlow API）</li><li>Operator 类型：BashOperator、PythonOperator、SQLExecuteQueryOperator</li><li>XCom：Task 间数据传递</li><li>Sensor：外部条件等待（文件、数据库、API）</li></ul></li><li><strong>调度策略</strong>： <ul><li>调度间隔：cron 表达式 vs timedelta</li><li>回填（Backfill）：历史数据重新处理</li><li>依赖管理：<code>trigger_rule</code>（all_success / one_success / all_done）</li></ul></li><li><strong>代码演示</strong>：基于 Airflow 构建数据仓库 ETL 调度系统</li></ul><h4 id="_14-2-数据质量与监控" tabindex="-1">14.2 数据质量与监控 <a class="header-anchor" href="#_14-2-数据质量与监控" aria-label="Permalink to “14.2 数据质量与监控”">​</a></h4><ul><li><strong>数据质量框架</strong>： <ul><li>完整性检查：行数校验、主键唯一性、外键引用完整性</li><li>准确性检查：值域校验、业务规则校验、统计分布检查</li><li>及时性检查：数据延迟监控、SLA 告警</li><li><strong>开源工具</strong>：Great Expectations / Soda / dbt tests</li></ul></li><li><strong>数据血缘追踪</strong>： <ul><li>列级血缘：字段从源到目标的流转路径</li><li>表级血缘：表依赖关系图</li><li>影响分析：上游变更影响范围评估</li></ul></li><li><strong>代码演示</strong>：实现数据质量检查框架（含告警通知）</li></ul><h3 id="模块六实战项目" tabindex="-1">模块六实战项目 <a class="header-anchor" href="#模块六实战项目" aria-label="Permalink to “模块六实战项目”">​</a></h3><p><strong>项目名称</strong>：数据管道实现用户行为分析平台</p><p><strong>项目内容</strong>：</p><ol><li>设计通用 ETL 框架（支持多源抽取、数据转换、批量加载）</li><li>基于 pandas/polars 实现数据清洗与聚合</li><li>基于 Airflow 构建 DAG 调度系统（定时执行、依赖管理、失败重试）</li><li>实现数据质量检查框架（完整性、准确性、及时性）</li><li>实现增量同步（基于 CDC / 时间戳）</li><li>构建用户行为分析数据管道（埋点采集 → 清洗 → 聚合 → 入仓）</li><li>数据可视化报表（基于 Metabase / Superset）</li></ol><hr><h2 id="模块七-测试与性能优化-1周" tabindex="-1">模块七：测试与性能优化（1周） <a class="header-anchor" href="#模块七-测试与性能优化-1周" aria-label="Permalink to “模块七：测试与性能优化（1周）”">​</a></h2><h3 id="教学目标-6" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-6" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>掌握 Python 测试体系：单元测试、集成测试、E2E 测试</li><li>掌握 Mock / Fixture / 参数化测试技术</li><li>掌握 Python 性能分析工具：cProfile、pyinstrument、memory_profiler</li><li>掌握 CPU 优化、内存优化、IO 优化的实战技巧</li><li>掌握 Cython / C 扩展加速方案</li></ol><h3 id="学习痛点-6" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-6" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>测试覆盖率低，上线频繁出问题，技术债越积越多</li><li>性能瓶颈难以定位，只知道加缓存，不知道从代码层面优化</li><li>不了解 Python 性能分析工具，凭感觉调优</li><li>遇到 CPU 密集型任务只知道换 Go，不知道 Cython / C 扩展</li></ul><h3 id="第十五周-测试体系与性能优化" tabindex="-1">第十五周：测试体系与性能优化 <a class="header-anchor" href="#第十五周-测试体系与性能优化" aria-label="Permalink to “第十五周：测试体系与性能优化”">​</a></h3><h4 id="_15-1-测试体系" tabindex="-1">15.1 测试体系 <a class="header-anchor" href="#_15-1-测试体系" aria-label="Permalink to “15.1 测试体系”">​</a></h4><ul><li><strong>单元测试</strong>： <ul><li><code>pytest</code> 核心功能：fixture、参数化、mark、conftest.py</li><li><code>unittest</code> 标准库与 pytest 对比</li><li>Mock 测试：<code>unittest.mock</code>（Mock / MagicMock / patch）、<code>pytest-mock</code></li><li>覆盖率：<code>pytest-cov</code> + <code>coverage.py</code>，分支覆盖 vs 行覆盖</li></ul></li><li><strong>集成测试</strong>： <ul><li>测试数据库：pytest fixtures + 事务回滚隔离</li><li>测试 HTTP 接口：<code>httpx</code> + ASGI 传输（不需启动真实服务）</li><li>TestClient（Starlette）/ Client（Django）测试客户端</li></ul></li><li><strong>E2E 测试</strong>： <ul><li>Playwright Python 版：浏览器自动化</li><li>API E2E：<code>httpx</code> + 真实服务启动</li></ul></li><li><strong>代码演示</strong>：为模块一的 Web 框架编写完整测试套件（覆盖率 &gt; 80%）</li></ul><h4 id="_15-2-性能分析工具" tabindex="-1">15.2 性能分析工具 <a class="header-anchor" href="#_15-2-性能分析工具" aria-label="Permalink to “15.2 性能分析工具”">​</a></h4><ul><li><strong>CPU 分析</strong>： <ul><li><code>cProfile</code> / <code>profile</code>：标准库性能分析器</li><li><code>pyinstrument</code>：调用栈采样分析器（低开销）</li><li><code>snakeviz</code>：cProfile 结果可视化</li><li><code>py-spy</code>：抽样分析（无需修改代码）</li></ul></li><li><strong>内存分析</strong>： <ul><li><code>memory_profiler</code>：逐行内存使用</li><li><code>tracemalloc</code>：标准库内存追踪</li><li><code>objgraph</code>：对象引用图与泄漏检测</li></ul></li><li><strong>代码演示</strong>：对 Web 框架进行性能分析并生成优化报告</li></ul><h4 id="_15-3-性能优化实战" tabindex="-1">15.3 性能优化实战 <a class="header-anchor" href="#_15-3-性能优化实战" aria-label="Permalink to “15.3 性能优化实战”">​</a></h4><ul><li><strong>CPU 优化</strong>： <ul><li>算法优化：时间复杂度与空间复杂度分析</li><li>向量化：用 numpy 替代循环</li><li>字典/集合查找：O(1) vs 列表 O(n)</li><li><code>__slots__</code> 减少属性查找开销</li></ul></li><li><strong>内存优化</strong>： <ul><li>生成器替代列表：<code>yield</code> vs <code>[]</code></li><li><code>__slots__</code> 节省实例内存</li><li>对象池与 <code>weakref</code></li><li>大文件处理：流式读取 vs 全量加载</li><li><code>gc</code> 模块：垃圾回收调优</li></ul></li><li><strong>IO 优化</strong>： <ul><li>异步 IO：<code>asyncio</code> 替代同步 IO</li><li>批量操作：减少网络往返</li><li>连接复用：连接池 vs 每次新建</li><li>零拷贝：<code>mmap</code> 内存映射文件</li></ul></li><li><strong>Cython / C 扩展</strong>： <ul><li>Cython 基础：<code>.pyx</code> 文件编译与使用</li><li>类型声明加速：<code>cdef</code> / <code>cpdef</code></li><li><code>ctypes</code> / <code>cffi</code> 调用 C 库</li><li><strong>代码演示</strong>：用 Cython 加速纯 Python 计算密集型函数（10x+ 提升）</li></ul></li></ul><h3 id="模块七实战项目" tabindex="-1">模块七实战项目 <a class="header-anchor" href="#模块七实战项目" aria-label="Permalink to “模块七实战项目”">​</a></h3><p><strong>项目名称</strong>：性能优化实战提升 Web 框架吞吐量</p><p><strong>项目内容</strong>：</p><ol><li>使用 pytest 编写完整测试套件（单元 + 集成 + E2E）</li><li>使用 cProfile / pyinstrument 定位性能瓶颈</li><li>CPU 优化：向量化、<code>__slots__</code>、算法优化</li><li>内存优化：生成器、对象池、GC 调优</li><li>IO 优化：异步化、连接池、批量操作</li><li>使用 Cython 加速热点函数</li><li>优化前后压测对比（QPS 提升 2-5 倍目标）</li></ol><hr><h2 id="模块八-工程化与-devops-1周" tabindex="-1">模块八：工程化与 DevOps（1周） <a class="header-anchor" href="#模块八-工程化与-devops-1周" aria-label="Permalink to “模块八：工程化与 DevOps（1周）”">​</a></h2><h3 id="教学目标-7" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-7" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>掌握 Python 项目工程化规范与最佳实践</li><li>掌握代码质量工具链：ruff、mypy、pre-commit</li><li>掌握 Docker 容器化与 Kubernetes 部署</li><li>掌握 CI/CD 流水线设计（GitHub Actions / GitLab CI）</li><li>掌握 Python 项目的安全审计与依赖管理</li></ol><h3 id="学习痛点-7" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-7" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>项目结构混乱，没有统一的工程化标准</li><li>代码风格不统一，code review 花大量时间在格式问题上</li><li>部署全靠手动操作，没有自动化流水线</li><li>依赖管理混乱：requirements.txt / setup.py / pyproject.toml 不知道用哪个</li></ul><h3 id="第十六周-工程化实践" tabindex="-1">第十六周：工程化实践 <a class="header-anchor" href="#第十六周-工程化实践" aria-label="Permalink to “第十六周：工程化实践”">​</a></h3><h4 id="_16-1-项目工程化规范" tabindex="-1">16.1 项目工程化规范 <a class="header-anchor" href="#_16-1-项目工程化规范" aria-label="Permalink to “16.1 项目工程化规范”">​</a></h4><ul><li><strong>项目结构设计</strong>： <ul><li>src layout vs flat layout</li><li>包管理与模块组织</li><li><code>pyproject.toml</code>（PEP 518 / PEP 621）统一配置</li></ul></li><li><strong>依赖管理</strong>： <ul><li><code>pip</code> + <code>requirements.txt</code>：基础方案</li><li><code>poetry</code> / <code>pdm</code> / <code>uv</code>：现代依赖管理对比</li><li>锁文件（lock file）与可复现构建</li></ul></li><li><strong>代码规范工具链</strong>： <ul><li><code>ruff</code>：极速 Linter + Formatter（替代 flake8 + black + isort）</li><li><code>mypy</code>：静态类型检查（Type Hint + 存根文件 stub）</li><li><code>pre-commit</code>：Git Hook 自动化</li><li><strong>代码演示</strong>：构建标准 Python 项目模板（pyproject.toml + ruff + mypy + pre-commit）</li></ul></li></ul><h4 id="_16-2-容器化与部署" tabindex="-1">16.2 容器化与部署 <a class="header-anchor" href="#_16-2-容器化与部署" aria-label="Permalink to “16.2 容器化与部署”">​</a></h4><ul><li><strong>Docker</strong>： <ul><li>Dockerfile 最佳实践：多阶段构建、层缓存优化</li><li>Python 镜像选型：<code>python:slim</code> vs <code>python:alpine</code> vs distroless</li><li><code>.dockerignore</code> 与构建上下文优化</li><li><strong>代码演示</strong>：为 Web 框架编写生产级 Dockerfile</li></ul></li><li><strong>Kubernetes</strong>： <ul><li>Deployment / Service / Ingress / ConfigMap / Secret</li><li>健康检查：liveness probe / readiness probe / startup probe</li><li>资源限制：requests / limits / HPA（水平自动伸缩）</li><li><strong>代码演示</strong>：编写 Kubernetes 部署清单（含 HPA 自动伸缩）</li></ul></li><li><strong>ASGI Server 部署</strong>： <ul><li>Gunicorn + Uvicorn worker：多进程 + 异步</li><li>worker 类型选型：uvicorn-worker / uvicorn-corn-worker</li><li>进程管理：worker 数量、超时、优雅重启</li></ul></li></ul><h4 id="_16-3-ci-cd-流水线" tabindex="-1">16.3 CI/CD 流水线 <a class="header-anchor" href="#_16-3-ci-cd-流水线" aria-label="Permalink to “16.3 CI/CD 流水线”">​</a></h4><ul><li><strong>GitHub Actions</strong>： <ul><li>Workflow / Job / Step 设计</li><li>矩阵测试：多 Python 版本 + 多操作系统</li><li>缓存优化：pip cache / pre-commit cache</li><li>发布流程：PyPI 发布 / Docker 镜像推送 / Kubernetes 部署</li></ul></li><li><strong>GitLab CI</strong>： <ul><li><code>.gitlab-ci.yml</code> 配置</li><li>Runner 选型：Shared Runner vs Specific Runner</li><li>环境管理：stages / environments / approvals</li></ul></li><li><strong>代码演示</strong>：构建完整 CI/CD 流水线（lint → test → build → deploy）</li></ul><h4 id="_16-4-安全审计" tabindex="-1">16.4 安全审计 <a class="header-anchor" href="#_16-4-安全审计" aria-label="Permalink to “16.4 安全审计”">​</a></h4><ul><li><strong>依赖安全扫描</strong>： <ul><li><code>safety</code> / <code>pip-audit</code>：已知漏洞扫描</li><li><code>bandit</code>：Python 代码安全静态分析</li><li>SCA（软件成分分析）与 SBOM</li></ul></li><li><strong>代码安全</strong>： <ul><li>SQL 注入防护：参数化查询</li><li>XSS / CSRF 防护：模板自动转义、CSRF Token</li><li>敏感信息管理：<code>.env</code> 文件、Vault、Kubernetes Secret</li><li><strong>代码演示</strong>：为项目配置安全扫描流水线</li></ul></li></ul><h3 id="模块八实战项目" tabindex="-1">模块八实战项目 <a class="header-anchor" href="#模块八实战项目" aria-label="Permalink to “模块八实战项目”">​</a></h3><p><strong>项目名称</strong>：工程化实践构建生产级应用</p><p><strong>项目内容</strong>：</p><ol><li>设计标准 Python 项目结构（src layout + pyproject.toml）</li><li>配置代码质量工具链（ruff + mypy + pre-commit）</li><li>编写生产级 Dockerfile（多阶段构建、镜像瘦身）</li><li>编写 Kubernetes 部署清单（Deployment + Service + HPA）</li><li>搭建 CI/CD 流水线（lint → test → security scan → build → deploy）</li><li>配置安全扫描（pip-audit + bandit）</li><li>将前七个模块的项目整合为完整的微服务系统并部署</li></ol><hr><h2 id="加餐-热门面试主题-穿插进行" tabindex="-1">加餐：热门面试主题（穿插进行） <a class="header-anchor" href="#加餐-热门面试主题-穿插进行" aria-label="Permalink to “加餐：热门面试主题（穿插进行）”">​</a></h2><h3 id="主题一-python-元编程深度" tabindex="-1">主题一：Python 元编程深度 <a class="header-anchor" href="#主题一-python-元编程深度" aria-label="Permalink to “主题一：Python 元编程深度”">​</a></h3><ul><li>元类（Metaclass）实战：ORM / Django Model 实现原理</li><li>描述符协议：property / classmethod / staticmethod 本质</li><li><code>__init_subclass__</code> 与插件注册机制</li><li>装饰器高级用法：带参数装饰器、类装饰器、装饰器类</li><li><strong>代码演示</strong>：使用元编程实现插件化架构</li></ul><h3 id="主题二-并发爬虫与数据采集" tabindex="-1">主题二：并发爬虫与数据采集 <a class="header-anchor" href="#主题二-并发爬虫与数据采集" aria-label="Permalink to “主题二：并发爬虫与数据采集”">​</a></h3><ul><li><code>aiohttp</code> + <code>asyncio</code> 异步爬虫</li><li><code>httpx</code> 异步 HTTP 客户端</li><li>反爬应对：代理池、请求频率控制、User-Agent 轮换</li><li>数据解析：<code>lxml</code> / <code>parsel</code> / <code>BeautifulSoup</code> 性能对比</li><li><strong>代码演示</strong>：实现分布式爬虫调度系统</li></ul><h3 id="主题三-python-内存模型与垃圾回收" tabindex="-1">主题三：Python 内存模型与垃圾回收 <a class="header-anchor" href="#主题三-python-内存模型与垃圾回收" aria-label="Permalink to “主题三：Python 内存模型与垃圾回收”">​</a></h3><ul><li>对象模型：一切皆对象，<code>PyObject</code> 结构</li><li>引用计数：<code>sys.getrefcount</code>、循环引用问题</li><li>标记-清除（Mark and Sweep）：分代回收</li><li><code>__del__</code> / <code>weakref</code> / <code>finalize</code> 资源管理</li><li><strong>代码演示</strong>：内存泄漏排查实战</li></ul><h3 id="主题四-设计模式在-python-中的实现" tabindex="-1">主题四：设计模式在 Python 中的实现 <a class="header-anchor" href="#主题四-设计模式在-python-中的实现" aria-label="Permalink to “主题四：设计模式在 Python 中的实现”">​</a></h3><ul><li>创建型：工厂方法、抽象工厂、单例（<code>__new__</code> / 元类 / 模块级）</li><li>结构型：适配器、装饰器、代理、外观</li><li>行为型：观察者、策略、命令、责任链</li><li>Python 特有模式：猴子补丁（Monkey Patching）、Mixin、协议类（Protocol）</li><li><strong>代码演示</strong>：用设计模式重构 Web 框架核心模块</li></ul><hr><h2 id="四大实战案例汇总" tabindex="-1">四大实战案例汇总 <a class="header-anchor" href="#四大实战案例汇总" aria-label="Permalink to “四大实战案例汇总”">​</a></h2><h3 id="案例一-手写-web-框架实现用户注册登录" tabindex="-1">案例一：手写 Web 框架实现用户注册登录 <a class="header-anchor" href="#案例一-手写-web-框架实现用户注册登录" aria-label="Permalink to “案例一：手写 Web 框架实现用户注册登录”">​</a></h3><ul><li><strong>关联模块</strong>：模块一</li><li><strong>核心技能</strong>：WSGI 规范、路由系统、中间件链、Session、模板引擎</li></ul><h3 id="案例二-异步高并发框架实现实时协作系统" tabindex="-1">案例二：异步高并发框架实现实时协作系统 <a class="header-anchor" href="#案例二-异步高并发框架实现实时协作系统" aria-label="Permalink to “案例二：异步高并发框架实现实时协作系统”">​</a></h3><ul><li><strong>关联模块</strong>：模块三</li><li><strong>核心技能</strong>：ASGI 规范、asyncio、WebSocket、异步 ORM、并发控制</li></ul><h3 id="案例三-微服务框架实现电商订单系统" tabindex="-1">案例三：微服务框架实现电商订单系统 <a class="header-anchor" href="#案例三-微服务框架实现电商订单系统" aria-label="Permalink to “案例三：微服务框架实现电商订单系统”">​</a></h3><ul><li><strong>关联模块</strong>：模块四</li><li><strong>核心技能</strong>：gRPC、服务治理、熔断降级、链路追踪、API 网关</li></ul><h3 id="案例四-分布式系统实现秒杀与异步订单" tabindex="-1">案例四：分布式系统实现秒杀与异步订单 <a class="header-anchor" href="#案例四-分布式系统实现秒杀与异步订单" aria-label="Permalink to “案例四：分布式系统实现秒杀与异步订单”">​</a></h3><ul><li><strong>关联模块</strong>：模块五</li><li><strong>核心技能</strong>：分布式锁、多级缓存、Celery 任务调度、消息队列、Snowflake ID</li></ul><hr><h2 id="学习路径建议" tabindex="-1">学习路径建议 <a class="header-anchor" href="#学习路径建议" aria-label="Permalink to “学习路径建议”">​</a></h2><h3 id="阶段一-基础夯实-第-1-3-周" tabindex="-1">阶段一：基础夯实（第 1-3 周） <a class="header-anchor" href="#阶段一-基础夯实-第-1-3-周" aria-label="Permalink to “阶段一：基础夯实（第 1-3 周）”">​</a></h3><ul><li>完成模块一：Web 框架</li><li>理解 WSGI/ASGI 原理与 Web 框架设计</li><li>完成案例一</li></ul><h3 id="阶段二-数据层能力-第-4-5-周" tabindex="-1">阶段二：数据层能力（第 4-5 周） <a class="header-anchor" href="#阶段二-数据层能力-第-4-5-周" aria-label="Permalink to “阶段二：数据层能力（第 4-5 周）”">​</a></h3><ul><li>完成模块二：ORM 框架</li><li>掌握元编程技术与数据库交互核心原理</li></ul><h3 id="阶段三-并发能力-第-6-7-周" tabindex="-1">阶段三：并发能力（第 6-7 周） <a class="header-anchor" href="#阶段三-并发能力-第-6-7-周" aria-label="Permalink to “阶段三：并发能力（第 6-7 周）”">​</a></h3><ul><li>完成模块三：异步编程与并发</li><li>掌握 asyncio 事件循环与异步框架设计</li><li>完成案例二</li></ul><h3 id="阶段四-分布式架构-第-8-12-周" tabindex="-1">阶段四：分布式架构（第 8-12 周） <a class="header-anchor" href="#阶段四-分布式架构-第-8-12-周" aria-label="Permalink to “阶段四：分布式架构（第 8-12 周）”">​</a></h3><ul><li>完成模块四：微服务框架</li><li>完成模块五：分布式系统与中间件</li><li>完成案例三、案例四</li></ul><h3 id="阶段五-数据工程-第-13-14-周" tabindex="-1">阶段五：数据工程（第 13-14 周） <a class="header-anchor" href="#阶段五-数据工程-第-13-14-周" aria-label="Permalink to “阶段五：数据工程（第 13-14 周）”">​</a></h3><ul><li>完成模块六：数据管道与 ETL</li><li>掌握数据处理与工作流调度</li></ul><h3 id="阶段六-工程化落地-第-15-16-周" tabindex="-1">阶段六：工程化落地（第 15-16 周） <a class="header-anchor" href="#阶段六-工程化落地-第-15-16-周" aria-label="Permalink to “阶段六：工程化落地（第 15-16 周）”">​</a></h3><ul><li>完成模块七：测试与性能优化</li><li>完成模块八：工程化与 DevOps</li><li>整合所有知识，构建生产级应用</li></ul><hr><h2 id="技术栈全景" tabindex="-1">技术栈全景 <a class="header-anchor" href="#技术栈全景" aria-label="Permalink to “技术栈全景”">​</a></h2><h3 id="核心语言与标准库" tabindex="-1">核心语言与标准库 <a class="header-anchor" href="#核心语言与标准库" aria-label="Permalink to “核心语言与标准库”">​</a></h3><ul><li>Python 3.12+</li><li><code>asyncio</code>、<code>multiprocessing</code>、<code>threading</code>、<code>concurrent.futures</code></li><li><code>collections</code>、<code>functools</code>、<code>itertools</code>、<code>contextlib</code></li><li><code>typing</code>、<code>dataclasses</code>、<code>pathlib</code></li></ul><h3 id="主流开源框架" tabindex="-1">主流开源框架 <a class="header-anchor" href="#主流开源框架" aria-label="Permalink to “主流开源框架”">​</a></h3><ul><li><strong>Web</strong>：Flask、Django、FastAPI、Starlette、Litestar</li><li><strong>ORM</strong>：SQLAlchemy、Django ORM、Tortoise ORM、SQLModel</li><li><strong>异步任务</strong>：Celery、Dramatiq、RQ（Redis Queue）、arq</li><li><strong>RPC</strong>：gRPC、Nameko、FastAPI</li><li><strong>消息队列</strong>：Kafka（confluent-kafka-python）、RabbitMQ（pika / aio-pika）</li><li><strong>数据处理</strong>：pandas、polars、numpy、PySpark</li><li><strong>工作流调度</strong>：Airflow、Prefect、Dagster</li></ul><h3 id="基础设施" tabindex="-1">基础设施 <a class="header-anchor" href="#基础设施" aria-label="Permalink to “基础设施”">​</a></h3><ul><li><strong>数据库</strong>：PostgreSQL、MySQL</li><li><strong>缓存</strong>：Redis、Memcached</li><li><strong>容器</strong>：Docker、Kubernetes</li><li><strong>监控</strong>：Prometheus、Grafana、OpenTelemetry、ELK / Loki</li><li><strong>CI/CD</strong>：GitHub Actions、GitLab CI</li><li><strong>注册中心</strong>：Consul、Etcd</li></ul><h3 id="开发工具链" tabindex="-1">开发工具链 <a class="header-anchor" href="#开发工具链" aria-label="Permalink to “开发工具链”">​</a></h3><ul><li><strong>包管理</strong>：poetry / pdm / uv</li><li><strong>Lint/Format</strong>：ruff</li><li><strong>类型检查</strong>：mypy / pyright</li><li><strong>测试</strong>：pytest、coverage.py、pytest-asyncio</li><li><strong>性能分析</strong>：pyinstrument、py-spy、memory_profiler</li><li><strong>安全扫描</strong>：pip-audit、bandit</li></ul><hr><h2 id="面试要点汇总" tabindex="-1">面试要点汇总 <a class="header-anchor" href="#面试要点汇总" aria-label="Permalink to “面试要点汇总”">​</a></h2><h3 id="高频面试题" tabindex="-1">高频面试题 <a class="header-anchor" href="#高频面试题" aria-label="Permalink to “高频面试题”">​</a></h3><ol><li><strong>Web 框架</strong>：WSGI vs ASGI 区别、Flask 路由原理、Django 中间件执行顺序、gunicorn worker 选型</li><li><strong>ORM</strong>：元类实现 ORM 原理、N+1 查询问题、SQLAlchemy Session 生命周期、连接池参数调优</li><li><strong>异步编程</strong>：事件循环原理、GIL 影响、asyncio.gather vs wait、async/await 与多线程混用</li><li><strong>微服务</strong>：gRPC 四种通信模式、服务注册发现流程、熔断器状态机、分布式链路追踪原理</li><li><strong>分布式系统</strong>：分布式锁实现方案、CAP 权衡、缓存一致性、消息队列选型</li><li><strong>数据处理</strong>：pandas 内存优化、ETL 增量同步方案、Airflow DAG 设计</li><li><strong>性能优化</strong>：cProfile 使用、内存泄漏排查、Cython 加速、<code>__slots__</code> 作用</li><li><strong>工程化</strong>：pyproject.toml 配置、Docker 多阶段构建、CI/CD 流水线设计</li></ol><h3 id="源码阅读清单" tabindex="-1">源码阅读清单 <a class="header-anchor" href="#源码阅读清单" aria-label="Permalink to “源码阅读清单”">​</a></h3><ul><li><code>asyncio</code> 事件循环实现（<code>asyncio/base_events.py</code>）</li><li><code>flask</code> 路由系统（<code>flask/sansio/app.py</code> + <code>werkzeug/routing/</code>）</li><li><code>django</code> 中间件链（<code>django/core/handlers/wsgi.py</code>）</li><li><code>SQLAlchemy</code> Query 编译器（<code>sqlalchemy/sql/compiler.py</code>）</li><li><code>celery</code> 任务执行流程（<code>celery/app/trace.py</code>）</li><li><code>starlette</code> ASGI 中间件（<code>starlette/middleware/</code>）</li></ul><hr><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to “附录”">​</a></h2><h3 id="推荐学习资源" tabindex="-1">推荐学习资源 <a class="header-anchor" href="#推荐学习资源" aria-label="Permalink to “推荐学习资源”">​</a></h3><ul><li>《Fluent Python》（流畅的 Python）— Luciano Ramalho</li><li>《Effective Python》— Brett Slatkin</li><li>《CPython Internals》— Anthony Shaw</li><li>Python 官方文档与 PEP（Python Enhancement Proposals）</li><li>Real Python 教程（realpython.com）</li></ul><h3 id="实践项目建议" tabindex="-1">实践项目建议 <a class="header-anchor" href="#实践项目建议" aria-label="Permalink to “实践项目建议”">​</a></h3><ul><li>个人博客系统（Web 框架 + ORM + 模板引擎）</li><li>短链接服务（缓存 + 分布式 ID + 异步任务）</li><li>即时通讯系统（WebSocket + 消息队列 + 异步框架）</li><li>微服务电商平台（全栈实践：Web + ORM + 微服务 + 分布式 + 消息队列）</li><li>数据分析平台（ETL + Airflow + 可视化）</li></ul><h3 id="go-课程-vs-python-课程对照" tabindex="-1">Go 课程 vs Python 课程对照 <a class="header-anchor" href="#go-课程-vs-python-课程对照" aria-label="Permalink to “Go 课程 vs Python 课程对照”">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>Go 实战训练营</th><th>Python 实战训练营</th></tr></thead><tbody><tr><td>一</td><td>Web 框架（Gin/Beego 原理）</td><td>Web 框架（Flask/Django 原理 + WSGI/ASGI）</td></tr><tr><td>二</td><td>ORM 框架（GORM 原理）</td><td>ORM 框架（SQLAlchemy 原理 + 元编程）</td></tr><tr><td>三</td><td>缓存系统（本地 + Redis）</td><td>异步编程与并发（asyncio + ASGI + 多进程/线程）</td></tr><tr><td>四</td><td>微服务框架（gRPC + 服务治理）</td><td>微服务框架（gRPC + 服务治理 + API 网关）</td></tr><tr><td>五</td><td>分布式事务（TCC/Saga）</td><td>分布式系统与中间件（分布式锁 + Celery + 消息队列）</td></tr><tr><td>六</td><td>消息队列（Kafka/RocketMQ）</td><td>数据管道与 ETL（pandas + Airflow + 数据质量）</td></tr><tr><td>七</td><td>日志与监控</td><td>测试与性能优化（pytest + cProfile + Cython）</td></tr><tr><td>八</td><td>工程化与最佳实践</td><td>工程化与 DevOps（Docker + K8s + CI/CD）</td></tr></tbody></table>',258)])])}const b=i(r,[["render",t]]);export{u as __pageData,b as default};
